from PIL import Image
import numpy as np
from scipy import ndimage
m=np.asarray(Image.open('/app/target.png').convert('L'))<128
lab,n=ndimage.label(m,np.ones((3,3),int)); print('components',[(int((lab==i).sum()), tuple(np.array(ndimage.find_objects(lab==i)[0]).__repr__() for _ in [])) for i in range(1,n+1)])
def runs(a):
 inds=np.flatnonzero(a)
 if not len(inds):return []
 cuts=np.where(np.diff(inds)>1)[0]+1
 return [(int(g[0]),int(g[-1])) for g in np.split(inds,cuts)]
for y in range(330,701,10):
 r=runs(m[y]);
 if r: print('row',y,r)
print('vertical')
for x in range(235,786,20):
 r=runs(m[:,x]);
 r=[(a,b) for a,b in r if b>=300 and a<=710]
 if r: print('col',x,r)
